/**
 * Account service — the only module views talk to.
 *
 * Transport: Abra API notifications used as a queue (see docs/QUEUE_CONTRACT.md).
 *  - `account.register` → key `site.abra.registrationKey` (what the game server polls)
 *  - everything else    → key `site.abra.eventsKey`
 *
 * Security model:
 *  - Plain passwords never leave the browser; only AzerothCore SRP6 salt/verifier.
 *  - E-mail verification and reset tokens are generated by the SERVER worker and
 *    e-mailed by it. The site only relays the token the user received, so the
 *    browser can never mark an e-mail as verified on its own.
 */
import { site } from '../config/site.js'
import { publish } from './abraApi.js'
import { sealPayload } from './queueCrypto.js'
import { makeRegistrationData } from './srp6.js'
import { normalizeEmail, normalizeUsername } from '../utils/validation.js'

export const SCHEMA_VERSION = 1

const uuid = () =>
  crypto.randomUUID?.() ??
  Array.from(crypto.getRandomValues(new Uint8Array(16)), (b) => b.toString(16).padStart(2, '0')).join('')

function envelope(type, data) {
  return {
    schema: SCHEMA_VERSION,
    type,
    id: uuid(),
    createdAt: new Date().toISOString(),
    source: `${site.slug}-site`,
    siteUrl: site.url,
    ...data
  }
}

async function send(key, payload) {
  if (!key) throw new Error('Queue key missing — set VITE_QUEUE_REGISTRATION_KEY / VITE_QUEUE_EVENTS_KEY in .env before building.')
  const content = await sealPayload(payload, site.abra.publicKey)
  await publish(key, payload.type, content)
  return { id: payload.id }
}

/** Queue a new game account. Uniqueness is enforced by the server against the auth DB. */
export async function registerAccount({ username, email, password, notifyDownloads = true, locale }) {
  const accountName = normalizeUsername(username)
  const srp6 = await makeRegistrationData(accountName, password)
  const payload = envelope('account.register', {
    account: {
      username: accountName,
      email: normalizeEmail(email),
      salt: srp6.salt, //           hex, 32 bytes LE → account.salt
      verifier: srp6.verifier, //   hex, 32 bytes LE → account.verifier
      expansion: 2, //              WotLK
      locale: locale ?? (typeof navigator !== 'undefined' ? navigator.language : 'en')
    },
    preferences: { notifyDownloads: Boolean(notifyDownloads) },
    consent: { termsVersion: site.auth.termsVersion, acceptedAt: new Date().toISOString() }
  })
  return send(site.abra.registrationKey, payload)
}

/** Relay the token from the verification e-mail. Server validates hash + expiry + single use. */
export function confirmEmail({ username, token }) {
  return send(site.abra.eventsKey, envelope('account.verify', { username: normalizeUsername(username), token }))
}

export function resendVerification({ email }) {
  return send(site.abra.eventsKey, envelope('account.verify.resend', { email: normalizeEmail(email) }))
}

/** Always resolves the same way whether or not the e-mail exists (no account enumeration). */
export function requestPasswordReset({ email }) {
  return send(site.abra.eventsKey, envelope('password.reset.request', { email: normalizeEmail(email) }))
}

/** New SRP6 credentials, authorised by the server-issued reset token. */
export async function resetPassword({ username, token, password }) {
  const accountName = normalizeUsername(username)
  const srp6 = await makeRegistrationData(accountName, password)
  return send(
    site.abra.eventsKey,
    envelope('password.reset', { username: accountName, token, salt: srp6.salt, verifier: srp6.verifier })
  )
}

export function subscribeToDownloads({ email }) {
  return send(site.abra.eventsKey, envelope('downloads.subscribe', { email: normalizeEmail(email) }))
}

export const isLoginAvailable = () => Boolean(site.auth.apiUrl)

/**
 * Login requires a synchronous answer, which a queue cannot give.
 * It is wired to VITE_AUTH_API_URL (`POST /auth/login`, httpOnly session cookie).
 */
export async function login({ login: identifier, password }) {
  if (!isLoginAvailable()) {
    const err = new Error('Account login opens with the official launch.')
    err.code = 'LOGIN_UNAVAILABLE'
    throw err
  }
  const res = await fetch(`${site.auth.apiUrl}/auth/login`, {
    method: 'POST',
    credentials: 'include',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ login: identifier.trim(), password })
  })
  if (res.status === 429) throw Object.assign(new Error('Too many attempts. Please wait a few minutes.'), { code: 'RATE_LIMITED' })
  if (!res.ok) throw Object.assign(new Error('Invalid username/e-mail or password.'), { code: 'INVALID_CREDENTIALS' })
  return res.json().catch(() => ({}))
}
